<?php
namespace App\Console\Commands;
use App\Models\User;use App\Services\Hr\Lifecycle\LifecycleService;use Illuminate\Console\Command;use Illuminate\Support\Facades\DB;
class ProcessScheduledHrExits extends Command{protected $signature='hr:process-scheduled-exits {--as-of=} {--company=} {--commit}';protected $description='Preview or finalize due, fully-cleared HR exit cases.';public function handle(LifecycleService$s):int{$date=$this->option('as-of')?:now()->toDateString();$q=DB::table('hr_exit_cases')->where('status','clearance')->whereDate('approved_last_working_date','<=',$date)->when($this->option('company'),fn($b,$v)=>$b->where('company_id',$v));$due=$q->get()->filter(fn($exit)=>!DB::table('hr_exit_clearance_items')->where('exit_case_id',$exit->id)->where('status','!=','completed')->exists());$this->info('Due and fully cleared exits: '.$due->count());if(!$this->option('commit'))return self::SUCCESS;if(!config('hr.features.employee_self_service',false)){$this->error('HR lifecycle feature is disabled.');return self::FAILURE;}$actor=User::query()->find(config('hr.system_user_id'));if(!$actor){$this->error('HR_SYSTEM_USER_ID must identify an existing system actor.');return self::FAILURE;}foreach($due as$exit)$s->finalizeExit($exit->id,$actor);return self::SUCCESS;}}
